/bin/bash -lc "cat > /tmp/caught-up-review.cjs <<'JS'
const {spawn}=require('node:child_process');
const fs=require('node:fs');
const browser=spawn('/root/.cache/ms-playwright/chromium-1140/chrome-linux/chrome',['--headless','--no-sandbox','--no-zygote','--single-process','--disable-dev-shm-usage','--disable-gpu','--disable-crashpad-for-testing','--remote-debugging-pipe','--user-data-dir=/tmp/caught-up-browser'],{stdio:['ignore','ignore','ignore','pipe','pipe']});
let id=0,buf='',pending=new Map();
browser.stdio[4].on('data',d=>{buf+=d;let pos;while((pos=buf.indexOf('\\0'))"'!==-1){const msg=JSON.parse(buf.slice(0,pos));buf=buf.slice(pos+1);if(pending.has(msg.id)){const p=pending.get(msg.id);pending.delete(msg.id);msg.error?p.reject(msg.error):p.resolve(msg.result);}}});
function send(method,params={},sessionId){return new Promise((resolve,reject)=>{pending.set(++id,{resolve,reject});browser.stdio[3].write(JSON.stringify({id,method,params,...(sessionId?{sessionId}:{})})+'"'\\0');});}
const timer=setTimeout(()=>{browser.kill();process.exit(1);},20000);
(async()=>{try{
const {targetId}=await send('Target.createTarget',{url:'about:blank'});
const {sessionId}=await send('Target.attachToTarget',{targetId,flatten:true});
const cdp=(m,p)=>send(m,p,sessionId);
await cdp('Page.enable');
await cdp('Emulation.setDeviceMetricsOverride',{width:320,height:256,deviceScaleFactor:1,mobile:false});
await cdp('Emulation.setEmulatedMedia',{features:[{name:'prefers-color-scheme',value:'light'}]});
const svg=fs.readFileSync('caught-up.svg','utf8');
await cdp('Page.setDocumentContent',{frameId:(await cdp('Page.getFrameTree')).frameTree.frame.id,html:'<html><body style=\"margin:0;display:grid;place-items:center;height:100vh;background:white\">'+svg+'</body></html>'});
const evaluate=async expression=>(await cdp('Runtime.evaluate',{expression,returnByValue:true})).result.value;
for(const t of [0,3500,7000]) console.log('Frame',t,await evaluate("'`(()=>{const a=document.querySelector('"'.mail').getAnimations()[0]; a.pause(); a.currentTime="'${t}; return getComputedStyle(document.querySelector('"'.mail')).transform;})()"'`));
let shot=await cdp('"'Page.captureScreenshot',{format:'png'});fs.writeFileSync('/tmp/caught-up-light.png',Buffer.from(shot.data,'base64'));
await cdp('Emulation.setEmulatedMedia',{features:[{name:'prefers-color-scheme',value:'dark'},{name:'prefers-reduced-motion',value:'reduce'}]});
await evaluate('document.body.style.background=\"#17212b\"');
console.log('Reduced motion:',await evaluate('getComputedStyle(document.querySelector(\".mail\")).animationName'));
console.log('Dark outline:',await evaluate('getComputedStyle(document.querySelector(\"rect\")).stroke'));
shot=await cdp('Page.captureScreenshot',{format:'png'});fs.writeFileSync('/tmp/caught-up-dark.png',Buffer.from(shot.data,'base64'));
}finally{clearTimeout(timer);browser.kill();}})().catch(e=>{console.error(e);process.exitCode=1});
